module rectangle_fix(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] n,\n    input wire [7:0] m,\n    input wire [3:0] k,\n    input wire [99:0] matrix [0:99],\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] TRANSPOSE = 3'd1;\n    localparam [2:0] CONVERT   = 3'd2;\n    localparam [2:0] PREP_CAND = 3'd3;\n    localparam [2:0] COMPUTE   = 3'd4;\n    localparam [2:0] DONE_ST   = 3'd5;\n    \n    reg [2:0] state, next_state;\n    \n    // Internal storage\n    reg [99:0] transposed [0:99];\n    reg [99:0] row_val [0:99];\n    reg [99:0] candidates [0:199];\n    reg [7:0] new_n, new_m;\n    reg [7:0] num_candidates;\n    reg [99:0] candidate;\n    reg [7:0] min_total;\n    reg [7:0] cand_idx;\n    reg [7:0] cycle_counter;\n    \n    // Loop counters\n    integer i, j;\n\n    // Popcount function\n    function [7:0] popcount;\n        input [99:0] vec;\n        integer k;\n        begin\n            popcount = 8'd0;\n            for (k = 0; k < 100; k = k + 1)\n                popcount = popcount + vec[k];\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            min_total <= 8'hFF;\n            cand_idx <= 8'd0;\n            num_candidates <= 8'd0;\n            cycle_counter <= 8'd0;\n            \n            for (i = 0; i < 100; i = i + 1) begin\n                transposed[i] <= 100'd0;\n                row_val[i] <= 100'd0;\n                if (i < 200) candidates[i] <= 100'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_counter <= 8'd0;\n                    if (start) begin\n                        state <= TRANSPOSE;\n                        min_total <= 8'hFF;\n                    end\n                end\n                \n                TRANSPOSE: begin\n                    // Transpose matrix if needed\n                    if (n < m) begin\n                        for (i = 0; i < 100; i = i + 1) begin\n                            for (j = 0; j < 100; j = j + 1) begin\n                                transposed[j][99-i] <= matrix[i][99-j];\n                            end\n                        end\n                        new_n <= m;\n                        new_m <= n;\n                    end else begin\n                        for (i = 0; i < 100; i = i + 1) begin\n                            transposed[i] <= matrix[i];\n                        end\n                        new_n <= n;\n                        new_m <= m;\n                    end\n                    state <= CONVERT;\n                end\n                \n                CONVERT: begin\n                    // Convert rows to bitmasks\n                    for (i = 0; i < new_n; i = i + 1) begin\n                        row_val[i] <= {100{1'b0}};\n                        for (j = 0; j < new_m; j = j + 1) begin\n                            row_val[i] <= {row_val[i][98:0], transposed[i][99-j]};
                        end\n                    end\n                    state <= PREP_CAND;\n                end\n                \n                PREP_CAND: begin\n                    // Generate candidates\n                    if (new_m <= k) begin\n                        num_candidates <= 8'd1 << new_m;\n                    end else begin\n                        num_candidates <= 8'd0;\n                        for (i = 0; i < new_n; i = i + 1) begin\n                            candidates[num_candidates] <= row_val[i];\n                            num_candidates <= num_candidates + 8'd1;\n                            candidates[num_candidates] <= ~row_val[i] & ((100'd1 << new_m) - 100'd1);\n                            num_candidates <= num_candidates + 8'd1;\n                        end\n                    end\n                    state <= COMPUTE;\n                    cand_idx <= 8'd0;\n                end\n                \n                COMPUTE: begin\n                    cycle_counter <= cycle_counter + 8'd1;\n                    if (cand_idx < num_candidates) begin\n                        // Get candidate pattern\n                        candidate <= (new_m <= k) ? cand_idx : candidates[cand_idx];\n                        \n                        // Calculate total flips\n                        reg [7:0] row_total = 8'd0;\n                        for (i = 0; i < new_n; i = i + 1) begin\n                            reg [99:0] diff = row_val[i] ^ candidate;\n                            reg [7:0] cnt = popcount(diff);\n                            row_total = row_total + ((cnt < (new_m - cnt)) ? cnt : (new_m - cnt));\n                        end\n                        \n                        if (row_total < min_total && row_total <= k) begin\n                            min_total <= row_total;\n                        end\n                        cand_idx <= cand_idx + 8'd1;\n                    end else begin\n                        state <= DONE_ST;\n                    end\n                    \n                    // Safety timeout\n                    if (cycle_counter > 8'd200) state <= DONE_ST;\n                end\n                \n                DONE_ST: begin\n                    result <= (min_total <= k) ? min_total : 8'hFF;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule